def is_prime(n):
    """
    判断一个数是否为质数

    Args:
        n: 待判断的数

    Returns:
        布尔值，表示是否为质数
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

